import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public int shortestSubarray(int[] nums, int k) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        Deque<Integer> deque = new ArrayDeque<>();
        int best = n + 1;
        for (int end = 0; end <= n; end++) {
            while (!deque.isEmpty() && prefix[end] - prefix[deque.peekFirst()] >= k) {
                best = Math.min(best, end - deque.pollFirst());
            }
            while (!deque.isEmpty() && prefix[end] <= prefix[deque.peekLast()]) {
                deque.pollLast();
            }
            deque.addLast(end);
        }
        return best == n + 1 ? -1 : best;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public int shortestSubarray(int[] nums, int k) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        int answer = -1;
        int left = 1;
        int right = n;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (existsWithinLength(prefix, k, mid)) {
                answer = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return answer;
    }

    private boolean existsWithinLength(long[] prefix, int k, int limit) {
        Deque<Integer> deque = new ArrayDeque<>();
        for (int end = 1; end < prefix.length; end++) {
            int start = end - 1;
            while (!deque.isEmpty() && prefix[start] <= prefix[deque.peekLast()]) {
                deque.pollLast();
            }
            deque.addLast(start);
            while (!deque.isEmpty() && deque.peekFirst() < end - limit) {
                deque.pollFirst();
            }
            if (!deque.isEmpty() && prefix[end] - prefix[deque.peekFirst()] >= k) {
                return true;
            }
        }
        return false;
    }
}

import java.util.Arrays;

class Solution {
    public int shortestSubarray(int[] nums, int k) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        long[] values = prefix.clone();
        Arrays.sort(values);
        int unique = 0;
        for (long value : values) {
            if (unique == 0 || values[unique - 1] != value) {
                values[unique++] = value;
            }
        }
        values = Arrays.copyOf(values, unique);

        FenwickMax tree = new FenwickMax(unique);
        tree.update(rank(values, prefix[0]), 0);
        int best = n + 1;
        for (int end = 1; end <= n; end++) {
            int limit = upperBound(values, prefix[end] - k);
            int start = tree.query(limit);
            if (start != -1) {
                best = Math.min(best, end - start);
            }
            tree.update(rank(values, prefix[end]), end);
        }
        return best == n + 1 ? -1 : best;
    }

    private int rank(long[] values, long target) {
        int left = 0;
        int right = values.length;
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (values[mid] < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left + 1;
    }

    private int upperBound(long[] values, long target) {
        int left = 0;
        int right = values.length;
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (values[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }

    private static class FenwickMax {
        private final int[] tree;

        FenwickMax(int size) {
            tree = new int[size + 1];
            Arrays.fill(tree, -1);
        }

        void update(int index, int value) {
            for (int i = index; i < tree.length; i += i & -i) {
                tree[i] = Math.max(tree[i], value);
            }
        }

        int query(int index) {
            int best = -1;
            for (int i = index; i > 0; i -= i & -i) {
                best = Math.max(best, tree[i]);
            }
            return best;
        }
    }
}

import java.util.Arrays;

class Solution {
    public int shortestSubarray(int[] nums, int k) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        long[] values = prefix.clone();
        Arrays.sort(values);
        int unique = 0;
        for (long value : values) {
            if (unique == 0 || values[unique - 1] != value) {
                values[unique++] = value;
            }
        }
        values = Arrays.copyOf(values, unique);

        SegmentTree tree = new SegmentTree(unique);
        tree.update(rank(values, prefix[0]), 0);
        int best = n + 1;
        for (int end = 1; end <= n; end++) {
            int limit = upperBound(values, prefix[end] - k) - 1;
            if (limit >= 0) {
                int start = tree.query(0, limit);
                if (start != -1) {
                    best = Math.min(best, end - start);
                }
            }
            tree.update(rank(values, prefix[end]), end);
        }
        return best == n + 1 ? -1 : best;
    }

    private int rank(long[] values, long target) {
        int left = 0;
        int right = values.length;
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (values[mid] < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }

    private int upperBound(long[] values, long target) {
        int left = 0;
        int right = values.length;
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (values[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }

    private static class SegmentTree {
        private final int size;
        private final int[] tree;

        SegmentTree(int count) {
            int n = 1;
            while (n < count) {
                n <<= 1;
            }
            size = n;
            tree = new int[size << 1];
            Arrays.fill(tree, -1);
        }

        void update(int index, int value) {
            int node = index + size;
            tree[node] = Math.max(tree[node], value);
            for (node >>= 1; node > 0; node >>= 1) {
                tree[node] = Math.max(tree[node << 1], tree[node << 1 | 1]);
            }
        }

        int query(int left, int right) {
            int best = -1;
            int l = left + size;
            int r = right + size;
            while (l <= r) {
                if ((l & 1) == 1) {
                    best = Math.max(best, tree[l++]);
                }
                if ((r & 1) == 0) {
                    best = Math.max(best, tree[r--]);
                }
                l >>= 1;
                r >>= 1;
            }
            return best;
        }
    }
}
